import numpy as np

# Define the sets A and B
A = list(range(-999, 1001)) # A = {-999, ..., 1000}
B = list(range(-1008, 1008)) # B = {-1008, ..., 1007}

K = 0
R = 1000

# Calculate K: number of pairs (m, n) such that m in A, n in B, and |m-n| <= R
for m in A:
    count_n = 0
    for n in B:
        if abs(m - n) <= R:
            count_n += 1
    K += count_n

print(f"The calculated value of K is: {K}")
